import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.CWWEQfK7.js";const p=JSON.parse('{"title":"User guide","description":"Choose a path for deployment, the first analysis, daily use, AI access, or repository updates.","frontmatter":{"page_id":"guide-index","title":"User guide","description":"Choose a path for deployment, the first analysis, daily use, AI access, or repository updates."},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md","lastUpdated":1786627803000}'),n={name:"en/guide/index.md"};function i(s,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="user-guide" tabindex="-1">User guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User guide&quot;">​</a></h1><p>You do not need to read every setting before trying Ershu. Start with the path that matches the job in front of you.</p><h2 id="i-want-to-get-it-running" tabindex="-1">I want to get it running <a class="header-anchor" href="#i-want-to-get-it-running" aria-label="Permalink to &quot;I want to get it running&quot;">​</a></h2><ol><li><a href="./quick-start">Deploy Ershu quickly on a Linux server</a></li><li><a href="./create-first-project">Create the first project</a></li><li><a href="./follow-a-run">Start and follow the first analysis</a></li></ol><p>This path downloads a deployment archive, installs the backend from PyPI, starts services with systemd, and serves the prebuilt frontend. The server does not need source repositories or Node.js.</p><h2 id="i-am-preparing-a-long-running-deployment" tabindex="-1">I am preparing a long-running deployment <a class="header-anchor" href="#i-am-preparing-a-long-running-deployment" aria-label="Permalink to &quot;I am preparing a long-running deployment&quot;">​</a></h2><p>Complete the one-machine check first, then read <a href="./production-deployment">move the quick deployment into production</a>. It covers HTTPS, production settings, backups, Worker privileges, and upgrade order.</p><h2 id="i-already-have-results-and-want-to-use-them" tabindex="-1">I already have results and want to use them <a class="header-anchor" href="#i-already-have-results-and-want-to-use-them" aria-label="Permalink to &quot;I already have results and want to use them&quot;">​</a></h2><ul><li><a href="./read-search-chat">Read the wiki, search the project, and ask questions</a></li><li><a href="./debugging">Debug analysis, retrieval, and relationship data</a></li></ul><p>Docs is best for understanding a topic, Search for locating an implementation, and project chat for combining several sources. Whichever route you use, exact conclusions should lead back to current source.</p><h2 id="i-want-coding-agents-to-read-the-project" tabindex="-1">I want coding agents to read the project <a class="header-anchor" href="#i-want-coding-agents-to-read-the-project" aria-label="Permalink to &quot;I want coding agents to read the project&quot;">​</a></h2><p>Follow <a href="./connect-mcp">Connect an MCP client</a>. Create a project-scoped key, then verify server identity, project discovery, wiki access, search, and source reading in stages. MCP is read-only and does not modify repositories for the client.</p><h2 id="i-want-project-facts-to-follow-repository-updates" tabindex="-1">I want project facts to follow repository updates <a class="header-anchor" href="#i-want-project-facts-to-follow-repository-updates" aria-label="Permalink to &quot;I want project facts to follow repository updates&quot;">​</a></h2><p>Read <a href="./automation">Track repository updates</a>. Scheduled polling and signed webhooks detect commits and create refresh runs. The Worker still performs the actual work.</p><h2 id="three-boundaries-that-prevent-common-mistakes" tabindex="-1">Three boundaries that prevent common mistakes <a class="header-anchor" href="#three-boundaries-that-prevent-common-mistakes" aria-label="Permalink to &quot;Three boundaries that prevent common mistakes&quot;">​</a></h2><ul><li><strong>A live process does not mean the whole system is ready.</strong> API health does not check Worker, Redis, or model channels.</li><li><strong>A queued run is not a completed run.</strong> Without a Worker, it remains in <code>queued</code>.</li><li><strong>A fact refresh does not rewrite the wiki.</strong> Automated refresh updates trees, code indexes, search indexes, and knowledge relationships. A document-producing analysis is still needed for new prose.</li></ul>',16)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
